3.query:
timeseries {
  user   = avg(macos.cpu.user),
  system = avg(macos.cpu.system),
  idle   = avg(macos.cpu.idle)
}, by: {host.name}
| filter in(host.name, array($MacHostName))

8.query:
timeseries {
  used  = avg(macos.memory.used),
  total = avg(macos.memory.total)
}, by: {host.name}
| filter in(host.name, array($MacHostName))
| fieldsAdd
    used_gb  = used[]  / 1073741824,
    total_gb = total[] / 1073741824
| fields timeframe, interval, host.name, used_gb, total_gb

11.query:
timeseries {
  swap_used  = avg(macos.memory.swap.used),
  swap_total = avg(macos.memory.swap.total)
}, by: {host.name}
| filter in(host.name, array($MacHostName))
| fieldsAdd
    swap_used_gb  = swap_used[]  / 1073741824,
    swap_total_gb = swap_total[] / 1073741824
| fields timeframe, interval, host.name, swap_used_gb, swap_total_gb

12.query:
timeseries {
  swap_used  = avg(macos.memory.swap.used),
  swap_total = avg(macos.memory.swap.total)
}, by: {host.name}
| filter in(host.name, array($MacHostName))
| fieldsAdd swap_pct = (swap_used[] / swap_total[]) * 100
| fields timeframe, interval, host.name, swap_pct

